// Fans out into one item per YouTube channel, so the HTTP Request node after this runs
// once per feed. Atom feeds are public and need no API key, which is the whole reason the
// watch tile works without another credential to keep alive.
//
// Edit this list to change what shows up on the homepage. A channel id is the `UC...`
// string in https://www.youtube.com/channel/<id>; a wrong one simply yields no entries
// rather than an error.
const CHANNELS = [
  'UCsBjURrPoezykLs9EqgamOA', // Fireship
  'UCbRP3c757lWg9M-U7TyEkXA', // Theo - t3.gg
  'UCZgt6AzoyjslHTC9dz0UoTw', // ByteByteGo
  'UCFbNIlppjAuEX4znoulh0Cw', // Web Dev Simplified
  'UCLq8gNoee7oXM7MvTdjyQvA', // Vercel
];

return CHANNELS.map((channelId) => ({
  json: { feedUrl: `https://www.youtube.com/feeds/videos.xml?channel_id=${channelId}` },
}));

// Weather and email are pulled from their nodes by name rather than from this node's
// input, because "Get Documents" now sits between Gmail and here.
const w = $('Get Weather').first().json;
const d = w.daily ?? {};
const c = w.current ?? {};

const CODES = {0:'clear',1:'mainly clear',2:'partly cloudy',3:'overcast',45:'fog',48:'fog',
  51:'light drizzle',53:'drizzle',55:'heavy drizzle',61:'light rain',63:'rain',65:'heavy rain',
  80:'rain showers',81:'rain showers',82:'heavy rain showers',95:'thunderstorm',96:'thunderstorm',99:'thunderstorm'};

const weather = [
  `Condition: ${CODES[d.weather_code?.[0]] ?? 'unknown'}`,
  `High ${d.temperature_2m_max?.[0]}C, low ${d.temperature_2m_min?.[0]}C`,
  `Right now ${c.temperature_2m}C, feels like ${c.apparent_temperature}C, humidity ${c.relative_humidity_2m}%`,
  `Chance of rain today: ${d.precipitation_probability_max?.[0]}%`,
  `Sunrise ${d.sunrise?.[0]?.slice(11)}, sunset ${d.sunset?.[0]?.slice(11)}`,
].join('\n');

// Marketing mail pads subjects and snippets with invisible characters. Strip them,
// otherwise they eat a large share of a small model's context.
const clean = (s) => String(s ?? '')
  .replace(/[\u034f\u200b-\u200d\ufeff\u00ad]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Shared by "Build Briefing Input" and "Shape Response", inlined into both by build.mjs's
// `@include`. The two Code nodes run in separate sandboxes but are bound by a contract:
// the agent names an action item by the email's position in the prompt list, and Shape
// Response resolves that number back to a real message by index. Filtering in one node
// only would shift the numbering and reply to the wrong person, so the filter lives here
// once and both sides get the identical copy.

// Automated senders that discard whatever is sent back. Replying is a dead letter, so
// they never earn a slot on the "Needs a reply" card -- and dropping them before the
// prompt is built keeps a 3B model's small context on mail that can actually be answered.
const NO_REPLY =
  /(^|[^a-z0-9])(no[._-]?reply|do[._-]?not[._-]?reply|donotreply|mailer[-_]?daemon|postmaster|bounces?)([^a-z0-9]|$)/i;

// `Genrey <no-reply@example.com>` -> `no-reply`. Matching only the local part keeps a
// domain like `noreply.example.com` from disqualifying a human sender there.
const localPart = (from) => {
  const angled = /<([^>]*)>/.exec(String(from ?? ''));
  const addr = (angled ? angled[1] : String(from ?? '')).trim();
  return addr.split('@')[0] ?? '';
};

const senderOf = (e) => e.From ?? e.from ?? e.headers?.from;

// "Always Output Data" on the Gmail node can emit one empty item; drop that too.
const repliableEmails = () => $('Get Emails').all()
  .map(i => i.json)
  .filter(e => e && (e.id || e.Subject || e.subject || e.snippet))
  .filter(e => !NO_REPLY.test(localPart(senderOf(e))));

// No-reply senders are dropped here rather than in the prompt, so the numbering the agent
// sees already matches what Shape Response resolves against.
//
// The cap keeps a busy inbox from crowding out the instructions in the model's 8192-token
// window. It MUST stay a prefix of repliableEmails(): Shape Response resolves email number
// N against the uncapped list, so anything but `slice(0, N)` shifts the mapping and replies
// to the wrong person.
const PROMPT_LIMIT = 20;
const raw = repliableEmails().slice(0, PROMPT_LIMIT);

const emails = raw.map((e, n) => {
  const from = clean(e.From ?? e.from ?? e.headers?.from) || '(unknown sender)';
  const subject = clean(e.Subject ?? e.subject ?? e.headers?.subject) || '(no subject)';
  const preview = clean(e.snippet).slice(0, 140);
  return `${n + 1}. From: ${from}\n   Subject: ${subject}\n   Preview: ${preview}`;
});

const emailBlock = emails.length
  ? emails.join('\n')
  : 'No new emails in the last 24 hours.';

// The calendar: the user's planner entries and the Philippine holidays they sit among, from
// the backend's /calendar/upcoming. Pulled by node name because Pick Channels and Get Video
// Feed sit between it and here. The node is allowed to fail (the backend may be restarting),
// in which case there is simply nothing to say about the week.
const calendarRows = (() => {
  try {
    return $('Get Calendar').all().map((item) => item.json).filter((row) => row && row.title);
  } catch {
    return [];
  }
})();

const calendar = calendarRows
  .map((row) => {
    const when = row.startTime ? `${row.date} ${String(row.startTime).slice(0, 5)}` : `${row.date} (all day)`;
    const what = row.kind === 'HOLIDAY' ? `${row.title} — holiday` : row.title;
    return `- ${when}: ${what}${row.notes ? ` (${row.notes})` : ''}`;
  })
  .join('\n');

const calendarBlock = calendar || 'Nothing on the calendar for the next seven days.';

// The date grounds the agent's follow-up question: its Postgres chat memory holds the
// briefings it wrote on earlier days, and without a date it cannot tell which was "yesterday".
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Manila' });

return [{ json: { briefing_input:
  `TODAY IS ${today}\n\nTODAY'S WEATHER (Quezon City)\n${weather}\n\nTHE WEEK AHEAD (calendar and Philippine holidays)\n${calendarBlock}\n\nRECENT EMAILS (${emails.length})\n${emailBlock}` } }];

// The webhook's response body -- this is the contract the homepage renders against
// (see nextjs-frontend/lib/briefing.ts).
//
// Anything the model should not be paraphrasing is copied straight from the source
// nodes: llama3.2:3b reliably invents temperatures, so only prose comes from the agent.

// The agent has no output parser, so its answer arrives as the raw JSON string the
// Ollama grammar produced. A model that still manages to emit something unparseable
// must not take the whole briefing down -- the weather, inbox count and documents below
// are all real data, and a briefing missing only its prose is still worth showing.
let b = {};
try {
  const answer = $json.output ?? $json.text ?? $json;
  b = (typeof answer === 'string' ? JSON.parse(answer) : answer) ?? {};
  // The grammar wraps the briefing in `output`; unwrap it if it is still there.
  if (b.output && typeof b.output === 'object') b = b.output;
} catch {
  b = {};
}

const w = $('Get Weather').first().json;
const d = w.daily ?? {};
const c = w.current ?? {};

const CODES = {0:'clear',1:'mainly clear',2:'partly cloudy',3:'overcast',45:'fog',48:'fog',
  51:'light drizzle',53:'drizzle',55:'heavy drizzle',61:'light rain',63:'rain',65:'heavy rain',
  80:'rain showers',81:'rain showers',82:'heavy rain showers',95:'thunderstorm',96:'thunderstorm',99:'thunderstorm'};

const str = (v) => (typeof v === 'string' ? v.trim() : '');
const arr = (v) => (Array.isArray(v) ? v : []);
const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : null);

const clean = (s) => String(s ?? '')
  .replace(/[͏​-‍﻿­]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Shared by "Build Briefing Input" and "Shape Response", inlined into both by build.mjs's
// `@include`. The two Code nodes run in separate sandboxes but are bound by a contract:
// the agent names an action item by the email's position in the prompt list, and Shape
// Response resolves that number back to a real message by index. Filtering in one node
// only would shift the numbering and reply to the wrong person, so the filter lives here
// once and both sides get the identical copy.

// Automated senders that discard whatever is sent back. Replying is a dead letter, so
// they never earn a slot on the "Needs a reply" card -- and dropping them before the
// prompt is built keeps a 3B model's small context on mail that can actually be answered.
const NO_REPLY =
  /(^|[^a-z0-9])(no[._-]?reply|do[._-]?not[._-]?reply|donotreply|mailer[-_]?daemon|postmaster|bounces?)([^a-z0-9]|$)/i;

// `Genrey <no-reply@example.com>` -> `no-reply`. Matching only the local part keeps a
// domain like `noreply.example.com` from disqualifying a human sender there.
const localPart = (from) => {
  const angled = /<([^>]*)>/.exec(String(from ?? ''));
  const addr = (angled ? angled[1] : String(from ?? '')).trim();
  return addr.split('@')[0] ?? '';
};

const senderOf = (e) => e.From ?? e.from ?? e.headers?.from;

// "Always Output Data" on the Gmail node can emit one empty item; drop that too.
const repliableEmails = () => $('Get Emails').all()
  .map(i => i.json)
  .filter(e => e && (e.id || e.Subject || e.subject || e.snippet))
  .filter(e => !NO_REPLY.test(localPart(senderOf(e))));

// The identical filter Build Briefing Input applied, so email number N in the prompt is
// emails[N - 1] here. That is what lets the model refer to an email by number and still
// produce an action item the homepage can actually reply to.
const emails = repliableEmails();

// The card shows this many. Every one of them is repliable, so a slot spent on an
// automated sender is a slot wasted -- hence the filter above rather than a bigger cap.
const CARD_SIZE = 5;

const toActionItem = (e, why) => ({
  message_id: str(e.id),
  thread_id: str(e.threadId),
  subject: clean(e.Subject ?? e.subject ?? e.headers?.subject) || '(no subject)',
  from: clean(e.From ?? e.from ?? e.headers?.from) || '(unknown sender)',
  snippet: clean(e.snippet).slice(0, 200),
  why,
});

// Action items are resolved back to the real message rather than trusted as the model
// wrote them: a 3B model garbles long subject lines, and a reply needs a genuine Gmail
// message id. An out-of-range or repeated number simply drops the item.
const flagged = arr(b.action_items)
  .map(a => ({ n: Number(a?.email_number), why: str(a?.why) }))
  .filter(a => Number.isInteger(a.n) && a.n >= 1 && a.n <= emails.length)
  .filter((a, i, all) => all.findIndex(x => x.n === a.n) === i)
  .slice(0, CARD_SIZE);

const flaggedIndexes = new Set(flagged.map(a => a.n));

// The agent decides what is urgent, but it routinely flags one or two and the card then
// looks empty next to a full inbox. The remaining slots are filled with the newest
// repliable mail it did not pick, in Gmail's own order. Those carry no `why` -- the
// homepage renders that line only when there is one -- so an agent-flagged email still
// reads as the one that needs attention.
const backfill = emails
  .map((e, i) => ({ e, n: i + 1 }))
  .filter(({ n }) => !flaggedIndexes.has(n))
  .slice(0, Math.max(0, CARD_SIZE - flagged.length))
  .map(({ e }) => toActionItem(e, ''));

const actionItems = flagged
  .map(({ n, why }) => toActionItem(emails[n - 1], why))
  .concat(backfill)
  .filter(a => a.message_id);

// "Get Documents" continues on error, so a backend that is down arrives as an item
// with no id rather than taking the whole briefing with it.
const library = $('Get Documents').all()
  .map(i => i.json)
  .filter(x => x && x.id);

// Fisher-Yates, used for both the library and the videos: every refresh surfaces a
// different slice rather than the same rows again.
const shuffle = (items) => {
  const out = items.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
};

// YouTube Atom feeds, one item per channel. Parsed by hand because the payload is small
// and predictable, and pulling an XML library into the Code node sandbox is not.
const unescapeXml = (s) => String(s ?? '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&amp;/g, '&');

const videos = [];
for (const item of $('Get Video Feed').all()) {
  const xml = typeof item.json?.data === 'string' ? item.json.data : '';
  // Everything before the first <entry> is the feed header, hence slice(1).
  for (const entry of xml.split('<entry>').slice(1)) {
    const id = /<yt:videoId>([^<]+)</.exec(entry)?.[1];
    if (!id) continue;
    videos.push({
      id,
      title: unescapeXml(/<title>([^<]*)</.exec(entry)?.[1]),
      channel: unescapeXml(/<name>([^<]*)</.exec(entry)?.[1]),
      published: /<published>([^<]*)</.exec(entry)?.[1] ?? null,
      url: `https://www.youtube.com/watch?v=${id}`,
    });
  }
}

return [{ json: {
  generated_at: new Date().toISOString(),
  greeting: str(b.greeting) || 'Good morning, Genrey.',
  weather: {
    location: 'Quezon City',
    condition: CODES[d.weather_code?.[0]] ?? (str(b.weather?.condition) || 'unknown'),
    high_c: num(d.temperature_2m_max?.[0]),
    low_c: num(d.temperature_2m_min?.[0]),
    current_c: num(c.temperature_2m),
    feels_like_c: num(c.apparent_temperature),
    humidity_percent: num(c.relative_humidity_2m),
    rain_chance_percent: num(d.precipitation_probability_max?.[0]),
    sunrise: d.sunrise?.[0] ?? null,
    sunset: d.sunset?.[0] ?? null,
    advice: str(b.weather?.advice),
  },
  email_summary: str(b.email_summary),
  email_count: emails.length,
  action_items: actionItems,
  tasks: arr(b.tasks).slice(0, 3).map(t => ({
    task: str(t?.task),
    reason: str(t?.reason),
  })).filter(t => t.task),
  followup_question: str(b.followup_question),
  documents: shuffle(library).slice(0, 3).map(x => ({
    id: x.id,
    title: str(x.title) || 'Untitled',
    contentType: str(x.contentType),
    ingestedAt: x.ingestedAt ?? null,
  })),
  document_count: library.length,
  videos: shuffle(videos).slice(0, 4),
} }];
